import{c as t,Q as o,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const f=JSON.parse('{"title":"Factory 2.0: From coding agents to software factories","description":"","frontmatter":{"url":"https://x.com/matanSF/status/2066578088184680920","title":"Factory 2.0: From coding agents to software factories","author":"Matan Grinberg","archived":"2026-06-16T00:00:00.000Z","handle":"@matanSF","published":"2026-06-15T00:00:00.000Z","stats":"856 likes · 93 retweets · 1460 bookmarks · 272769 views","tags":["software-factory","agentic-engineering","enterprise-ai","factory-app","sdlc"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-15-@matanSF-680920.md","filePath":"research/tweets/2026-06-15-@matanSF-680920.md","lastUpdated":1785909234000}'),a={name:"research/tweets/2026-06-15-@matanSF-680920.md"};function r(i,e,l,d,c,u){return o(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="factory-2-0-from-coding-agents-to-software-factories-—-matansf" tabindex="-1">Factory 2.0: From coding agents to software factories — @matanSF <a class="header-anchor" href="#factory-2-0-from-coding-agents-to-software-factories-—-matansf" aria-label="Permalink to &quot;Factory 2.0: From coding agents to software factories — @matanSF&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/matanSF/status/2066578088184680920" target="_blank" rel="noreferrer">https://x.com/matanSF/status/2066578088184680920</a><strong>作者</strong>：Matan Grinberg（@matanSF） <strong>發布日期</strong>：2026-06-15 <strong>收錄日期</strong>：2026-06-16 <strong>類型</strong>：Twitter Article <strong>統計</strong>：856 likes · 93 retweets · 1460 bookmarks · 272769 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><h2 id="in-2023-we-launched-factory-with-the-mission-to-bring-autonomy-to-software-engineering-while-others-were-using-models-to-speed-up-coding-we-set-out-to-deploy-autonomous-droids-across-the-enterprise-software-development-lifecycle-today-we-are-announcing-the-next-phase-in-the-future-of-software-engineering-improving-the-productivity-of-individual-engineers-is-no-longer-enough-unlocking-organization-wide-productivity-requires-an-interconnected-agent-native-end-to-end-system-this-system-must-improve-over-time-by-observing-itself-the-incremental-units-of-this-system-are-ai-agents-this-system-will-be-built-by-engineers-and-in-turn-will-build-their-software-this-system-is-the-software-factory" tabindex="-1">In 2023, we launched Factory with the mission to bring autonomy to software engineering. While others were using models to speed up coding, we set out to deploy autonomous Droids across the enterprise software development lifecycle. Today we are announcing the next phase in the future of software engineering. Improving the productivity of individual engineers is no longer enough. Unlocking organization-wide productivity requires an interconnected, agent-native, end-to-end system. This system must improve over time by observing itself. The incremental units of this system are AI agents. This system will be built by engineers, and in turn will build their software. This system is the software factory. <a class="header-anchor" href="#in-2023-we-launched-factory-with-the-mission-to-bring-autonomy-to-software-engineering-while-others-were-using-models-to-speed-up-coding-we-set-out-to-deploy-autonomous-droids-across-the-enterprise-software-development-lifecycle-today-we-are-announcing-the-next-phase-in-the-future-of-software-engineering-improving-the-productivity-of-individual-engineers-is-no-longer-enough-unlocking-organization-wide-productivity-requires-an-interconnected-agent-native-end-to-end-system-this-system-must-improve-over-time-by-observing-itself-the-incremental-units-of-this-system-are-ai-agents-this-system-will-be-built-by-engineers-and-in-turn-will-build-their-software-this-system-is-the-software-factory" aria-label="Permalink to &quot;In 2023, we launched Factory with the mission to bring autonomy to software engineering.  While others were using models to speed up coding, we set out to deploy autonomous Droids across the enterprise software development lifecycle. Today we are announcing the next phase in the future of software engineering.
Improving the productivity of individual engineers is no longer enough. Unlocking organization-wide productivity requires an interconnected, agent-native, end-to-end system. This system must improve over time by observing itself. The incremental units of this system are AI agents. This system will be built by engineers, and in turn will build their software.
This system is the software factory.&quot;">​</a></h2><h2 id="the-software-factory-starts-with-signals-from-the-outside-world-bug-reports-internal-conversations-customer-feedback-business-requirements-these-signals-get-triaged-and-turned-into-planned-changes-these-changes-are-built-tested-reviewed-secured-shipped-and-monitored-monitoring-that-deployed-software-generates-more-signals-the-entire-system-is-a-continuous-feedback-loop-almost-no-one-has-meaningfully-instrumented-this-loop-to-be-fully-ai-driven-we-are-still-early-but-the-proliferation-of-software-factories-is-going-to-happen-very-quickly-a-robust-software-factory-must-have-model-independence-every-model-has-a-different-trade-off-of-cost-performance-and-speed-no-one-model-fits-every-need-within-an-enterprise-your-software-factory-must-allow-your-organization-to-deliberately-choose-different-models-or-rely-on-a-router-to-automatically-or-rule-based-select-the-best-model-for-any-given-task-as-models-commoditize-costs-decrease-while-speed-and-performance-increase-sovereign-intelligence-you-must-be-the-sovereign-of-your-software-factory-whether-fully-hosted-in-the-cloud-bring-your-own-key-self-hosted-data-plane-eu-specific-or-completely-air-gapped-with-no-external-network-access-sovereignty-means-more-than-choosing-where-the-system-runs-it-means-owning-a-system-that-learns-from-itself-feeding-every-agent-session-code-review-and-resolved-incident-back-into-the-loop-the-more-you-invest-in-your-software-factory-the-more-capable-it-becomes-and-that-capability-stays-with-you-inside-your-walls-under-your-control-continual-learning-and-self-improvement-every-stage-of-the-software-development-lifecycle-must-be-instrumented-when-code-review-security-analysis-documentation-qa-and-incident-response-all-run-on-the-same-platform-they-share-the-same-agent-core-the-same-model-router-the-same-organizational-context-a-security-finding-informs-the-code-review-a-deployment-triggers-a-documentation-update-an-incident-correlates-with-the-pr-that-caused-it-every-additional-automation-integration-or-customization-flows-to-the-entire-organization-at-once-the-router-itself-learns-to-optimizes-resources-the-assembly-line-should-span-the-full-floor-of-the-software-factory" tabindex="-1">The software factory starts with signals from the outside world: bug reports, internal conversations, customer feedback, business requirements. These signals get triaged and turned into planned changes. These changes are built, tested, reviewed, secured, shipped, and monitored. Monitoring that deployed software generates more signals. The entire system is a continuous feedback loop. Almost no one has meaningfully instrumented this loop to be fully AI-driven. We are still early, but the proliferation of software factories is going to happen very quickly. A robust software factory must have: Model Independence. Every model has a different trade-off of cost, performance, and speed. No one model fits every need within an enterprise. Your software factory must allow your organization to deliberately choose different models, or rely on a Router to automatically (or rule-based) select the best* model for any given task. As models commoditize, costs decrease while speed and performance increase. Sovereign Intelligence. You must be the sovereign of your software factory. Whether fully hosted in the cloud, bring-your-own-key, self-hosted data plane, EU-specific, or completely air-gapped with no external network access. Sovereignty means more than choosing where the system runs. It means owning a system that learns from itself, feeding every agent session, code review, and resolved incident back into the loop. The more you invest in your software factory, the more capable it becomes, and that capability stays with you, inside your walls, under your control. Continual Learning and Self-Improvement. Every stage of the software development lifecycle must be instrumented. When code review, security analysis, documentation, QA, and incident response all run on the same platform, they share the same agent core, the same model router, the same organizational context. A security finding informs the code review. A deployment triggers a documentation update. An incident correlates with the PR that caused it. Every additional automation, integration, or customization flows to the entire organization at once. The router itself learns to optimizes resources. The assembly line should span the full floor of the software factory. <a class="header-anchor" href="#the-software-factory-starts-with-signals-from-the-outside-world-bug-reports-internal-conversations-customer-feedback-business-requirements-these-signals-get-triaged-and-turned-into-planned-changes-these-changes-are-built-tested-reviewed-secured-shipped-and-monitored-monitoring-that-deployed-software-generates-more-signals-the-entire-system-is-a-continuous-feedback-loop-almost-no-one-has-meaningfully-instrumented-this-loop-to-be-fully-ai-driven-we-are-still-early-but-the-proliferation-of-software-factories-is-going-to-happen-very-quickly-a-robust-software-factory-must-have-model-independence-every-model-has-a-different-trade-off-of-cost-performance-and-speed-no-one-model-fits-every-need-within-an-enterprise-your-software-factory-must-allow-your-organization-to-deliberately-choose-different-models-or-rely-on-a-router-to-automatically-or-rule-based-select-the-best-model-for-any-given-task-as-models-commoditize-costs-decrease-while-speed-and-performance-increase-sovereign-intelligence-you-must-be-the-sovereign-of-your-software-factory-whether-fully-hosted-in-the-cloud-bring-your-own-key-self-hosted-data-plane-eu-specific-or-completely-air-gapped-with-no-external-network-access-sovereignty-means-more-than-choosing-where-the-system-runs-it-means-owning-a-system-that-learns-from-itself-feeding-every-agent-session-code-review-and-resolved-incident-back-into-the-loop-the-more-you-invest-in-your-software-factory-the-more-capable-it-becomes-and-that-capability-stays-with-you-inside-your-walls-under-your-control-continual-learning-and-self-improvement-every-stage-of-the-software-development-lifecycle-must-be-instrumented-when-code-review-security-analysis-documentation-qa-and-incident-response-all-run-on-the-same-platform-they-share-the-same-agent-core-the-same-model-router-the-same-organizational-context-a-security-finding-informs-the-code-review-a-deployment-triggers-a-documentation-update-an-incident-correlates-with-the-pr-that-caused-it-every-additional-automation-integration-or-customization-flows-to-the-entire-organization-at-once-the-router-itself-learns-to-optimizes-resources-the-assembly-line-should-span-the-full-floor-of-the-software-factory" aria-label="Permalink to &quot;The software factory starts with signals from the outside world: bug reports, internal conversations, customer feedback, business requirements. These signals get triaged and turned into planned changes. These changes are built, tested, reviewed, secured, shipped, and monitored. Monitoring that deployed software generates more signals. The entire system is a continuous feedback loop. Almost no one has meaningfully instrumented this loop to be fully AI-driven. We are still early, but the proliferation of software factories is going to happen very quickly.
A robust software factory must have:
Model Independence.
Every model has a different trade-off of cost, performance, and speed. No one model fits every need within an enterprise. Your software factory must allow your organization to deliberately choose different models, or rely on a Router to automatically (or rule-based) select the best* model for any given task. As models commoditize, costs decrease while speed and performance increase.
Sovereign Intelligence.
You must be the sovereign of your software factory. Whether fully hosted in the cloud, bring-your-own-key, self-hosted data plane, EU-specific, or completely air-gapped with no external network access. Sovereignty means more than choosing where the system runs. It means owning a system that learns from itself, feeding every agent session, code review, and resolved incident back into the loop. The more you invest in your software factory, the more capable it becomes, and that capability stays with you, inside your walls, under your control.
Continual Learning and Self-Improvement.
Every stage of the software development lifecycle must be instrumented. When code review, security analysis, documentation, QA, and incident response all run on the same platform, they share the same agent core, the same model router, the same organizational context. A security finding informs the code review. A deployment triggers a documentation update. An incident correlates with the PR that caused it. Every additional automation, integration, or customization flows to the entire organization at once. The router itself learns to optimizes resources. The assembly line should span the full floor of the software factory.&quot;">​</a></h2><h2 id="we-have-been-building-software-factories-with-our-customers-for-the-last-few-months-software-factories-are-already-in-production-across-the-world-s-largest-organizations-including-nvidia-ey-adobe-palo-alto-networks-adyen-blackstone-wipro-comarch-and-more-圖-1-no-organization-starts-with-a-fully-autonomous-software-factory-autonomy-is-a-maturation-process-that-is-gradual-and-specific-to-every-organization-s-readiness-and-comfort-level-deploying-autonomy-across-the-organization-happens-through-deliberate-engineering-effort-to-codify-workflows-and-standardize-processes-factory-enables-a-spectrum-of-autonomy-over-time-not-every-process-should-use-long-horizon-autonomous-tasks-well-defined-measurable-tasks-run-with-simple-droid-agents-or-skills-automations-coordinate-recurring-workflows-with-a-shared-objective-and-memory-remote-and-persistent-execution-leverages-droid-computers-for-long-running-or-local-agents-multi-agent-autonomous-execution-called-missions-solve-complex-tasks-over-hours-or-days-by-decomposing-work-into-parallel-tracks-to-handle-different-autonomous-processes-are-used-for-varying-requirements-based-on-the-level-of-human-guidance-required-the-information-sensitivity-and-the-level-of-agent-readiness-organizations-that-invest-in-their-autonomous-software-development-will-see-engineering-outcomes-surge-while-owning-decisions-around-cost-quality-and-context-the-role-of-engineers-is-all-the-more-important-in-this-new-era-no-longer-will-they-be-the-sole-custodians-of-building-the-software-instead-they-will-be-responsible-for-building-the-factories-that-build-the-software-with-this-comes-the-responsibility-of-governance-safety-and-the-ownership-of-business-outcomes-the-next-era-of-software-development-will-be-engineering-led-and-will-see-engineering-responsibilities-grow-to-span-across-the-business-itself-software-factories-are-not-built-in-a-day-but-the-best-day-to-start-building-your-factory-is-today-today-we-are-expanding-this-functionality-with-visibility-to-manage-your-software-factory-directly-in-the-factory-desktop-app" tabindex="-1">We have been building software factories with our customers for the last few months. Software factories are already in production across the world’s largest organizations including NVIDIA, EY, Adobe, Palo Alto Networks, Adyen, Blackstone, Wipro, Comarch and more. [圖 1] No organization starts with a fully autonomous software factory. Autonomy is a maturation process that is gradual and specific to every organization’s readiness and comfort level. Deploying autonomy across the organization happens through deliberate engineering effort to codify workflows and standardize processes. Factory enables a spectrum of autonomy over time. Not every process should use long-horizon autonomous tasks. Well-defined, measurable tasks run with simple Droid agents or skills. Automations coordinate recurring workflows with a shared objective and memory. Remote and persistent execution leverages Droid Computers for long running or local agents. Multi-agent autonomous execution called Missions solve complex tasks over hours or days by decomposing work into parallel tracks to handle. Different autonomous processes are used for varying requirements based on the level of human guidance required, the information sensitivity, and the level of Agent Readiness. Organizations that invest in their autonomous software development will see engineering outcomes surge, while owning decisions around cost, quality and context. The role of engineers is all the more important in this new era. No longer will they be the sole custodians of building the software. Instead, they will be responsible for building the factories that build the software. With this comes the responsibility of governance, safety, and the ownership of business outcomes. The next era of software development will be engineering-led and will see engineering responsibilities grow to span across the business itself. Software factories are not built in a day, but the best day to start building your Factory is today. Today we are expanding this functionality with visibility to manage your software factory directly in the Factory Desktop App. <a class="header-anchor" href="#we-have-been-building-software-factories-with-our-customers-for-the-last-few-months-software-factories-are-already-in-production-across-the-world-s-largest-organizations-including-nvidia-ey-adobe-palo-alto-networks-adyen-blackstone-wipro-comarch-and-more-圖-1-no-organization-starts-with-a-fully-autonomous-software-factory-autonomy-is-a-maturation-process-that-is-gradual-and-specific-to-every-organization-s-readiness-and-comfort-level-deploying-autonomy-across-the-organization-happens-through-deliberate-engineering-effort-to-codify-workflows-and-standardize-processes-factory-enables-a-spectrum-of-autonomy-over-time-not-every-process-should-use-long-horizon-autonomous-tasks-well-defined-measurable-tasks-run-with-simple-droid-agents-or-skills-automations-coordinate-recurring-workflows-with-a-shared-objective-and-memory-remote-and-persistent-execution-leverages-droid-computers-for-long-running-or-local-agents-multi-agent-autonomous-execution-called-missions-solve-complex-tasks-over-hours-or-days-by-decomposing-work-into-parallel-tracks-to-handle-different-autonomous-processes-are-used-for-varying-requirements-based-on-the-level-of-human-guidance-required-the-information-sensitivity-and-the-level-of-agent-readiness-organizations-that-invest-in-their-autonomous-software-development-will-see-engineering-outcomes-surge-while-owning-decisions-around-cost-quality-and-context-the-role-of-engineers-is-all-the-more-important-in-this-new-era-no-longer-will-they-be-the-sole-custodians-of-building-the-software-instead-they-will-be-responsible-for-building-the-factories-that-build-the-software-with-this-comes-the-responsibility-of-governance-safety-and-the-ownership-of-business-outcomes-the-next-era-of-software-development-will-be-engineering-led-and-will-see-engineering-responsibilities-grow-to-span-across-the-business-itself-software-factories-are-not-built-in-a-day-but-the-best-day-to-start-building-your-factory-is-today-today-we-are-expanding-this-functionality-with-visibility-to-manage-your-software-factory-directly-in-the-factory-desktop-app" aria-label="Permalink to &quot;We have been building software factories with our customers for the last few months. Software factories are already in production across the world’s largest organizations including NVIDIA, EY, Adobe, Palo Alto Networks, Adyen, Blackstone, Wipro, Comarch and more.
[圖 1]
No organization starts with a fully autonomous software factory. Autonomy is a maturation process that is gradual and specific to every organization’s readiness and comfort level. Deploying autonomy across the organization happens through deliberate engineering effort to codify workflows and standardize processes. 
Factory enables a spectrum of autonomy over time. Not every process should use long-horizon autonomous tasks. Well-defined, measurable tasks run with simple Droid agents or skills. Automations coordinate recurring workflows with a shared objective and memory. Remote and persistent execution leverages Droid Computers for long running or local agents. Multi-agent autonomous execution called Missions solve complex tasks over hours or days by decomposing work into parallel tracks to handle. Different autonomous processes are used for varying requirements based on the level of human guidance required, the information sensitivity, and the level of Agent Readiness.
Organizations that invest in their autonomous software development will see engineering outcomes surge, while owning decisions around cost, quality and context. The role of engineers is all the more important in this new era. No longer will they be the sole custodians of building the software. Instead, they will be responsible for building the factories that build the software. With this comes the responsibility of governance, safety, and the ownership of business outcomes. The next era of software development will be engineering-led and will see engineering responsibilities grow to span across the business itself.
Software factories are not built in a day, but the best day to start building your Factory is today.
Today we are expanding this functionality with visibility to manage your software factory directly in the Factory Desktop App.&quot;">​</a></h2><ul><li>best can be set according to cost, performance, speed, or some combination.</li></ul><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Factory 2.0 提出「軟體工廠」架構——AI agent 從個人生產力工具升格為組織層級的全 SDLC 自動化系統，工程師角色從「建構軟體」轉為「建構建構軟體的工廠」。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>個人效率已到天花板</strong>：提升單個工程師生產力不夠，組織層級生產力需要互聯的 agent-native 端到端系統，且能自我觀察並隨時間改進</li><li><strong>軟體工廠三大特性</strong>：Model Independence（不同任務選最適模型）、Sovereign Intelligence（數據主權 + 自我學習，能力留在組織內部）、Continual Learning（全 SDLC 儀器化，安全發現回饋 code review，部署觸發文件更新）</li><li><strong>自主性漸進成熟框架</strong>：簡單 Droid skills → coordinated Automations（共享目標/記憶）→ remote Droid Computers（長時間運行）→ multi-agent Missions（複雜任務並行分解，數小時至數天），按明確性/敏感性/Agent Readiness 選擇</li><li><strong>工程師角色的根本轉型</strong>：從軟體的唯一建構者 → 工廠的建構者，負責 governance、safety 和 business outcomes</li><li><strong>已在頂級企業部署</strong>：NVIDIA、EY、Adobe、Palo Alto Networks、Adyen、Blackstone、Wipro 等已在生產環境運行軟體工廠</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li><strong>Factory 組件層次</strong>：Droid agents → Automations → Droid Computers → Missions</li><li><strong>Model Router</strong>：自動/規則選最佳模型（cost/performance/speed 組合）</li><li><strong>Factory Desktop App</strong>：可視化管理軟體工廠（新發布功能）</li><li><strong>生產客戶</strong>：NVIDIA, EY, Adobe, Palo Alto Networks, Adyen, Blackstone, Wipro, Comarch</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>產品發布文案，缺乏量化數據</strong>：「軟體工廠」概念框架宏大，但無具體效能指標（PR merge rate、bug density、cycle time 改善幅度）佐證</li><li><strong>自學習迴圈的風險未觸及</strong>：「安全發現回饋 code review」等跨階段回饋聽起來理想，但若 AI 在某階段產生系統性錯誤，整個工廠如何防止錯誤累積放大未作說明</li><li><strong>大型企業客戶有 survivor bias</strong>：所有案例都是頂級企業，框架對 SMB 或技術債嚴重的中型組織的適用性不明</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>5/10</td><td>高層次框架，無直接可套用的技術配置或 prompt</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>「軟體工廠」系統比喻與自主性成熟度框架有助於組織思考</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>企業名單是 social proof，缺乏量化效能數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>Missions/Automations/Droid Computers 組件描述淺薄，無技術細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>三大特性原則（Model Independence、Sovereign Intelligence 等）可引申至任何大型 AI 系統</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.7/10</strong></td><td>5×0.3+7×0.2+5×0.2+5×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（僅歸檔） <strong>理由</strong>：產品發布文案，框架概念層次高但缺乏可操作細節，分數未達 6 分整合門檻。</p>`,21)])])}const m=t(a,[["render",r]]);export{f as __pageData,m as default};
